/* ==========================================
   WCAG 2.2 Focus Style
   Applies to all interactive elements
   ========================================== */

/* Links */
a:focus,
a:focus-visible,

/* Form elements */
input:focus,
input:focus-visible,
textarea:focus,
textarea:focus-visible,
select:focus,
select:focus-visible,

/* Buttons */
button:focus,
button:focus-visible,

/* Forsta navigation */
.cf-navigation-next:focus,
.cf-navigation-next:focus-visible,
.cf-navigation-back:focus,
.cf-navigation-back:focus-visible,
.SRC_navigation_save:focus,
.SRC_navigation_save:focus-visible,

/* Forsta controls */
.cf-checkbox:focus,
.cf-checkbox:focus-visible,
.cf-radio:focus,
.cf-radio:focus-visible,

/* Open answers */
.cf-open-answer__input:focus,
.cf-open-answer__input:focus-visible,
.cf-text-box:focus,
.cf-text-box:focus-visible,
.cf-text-box--number:focus,
.cf-text-box--number:focus-visible,

/* Details  Summary */
details:focus,
details:focus-visible {
	outline: none;
}

summary:focus,
summary:focus-visible {
    outline: var(--focus-width) solid var(--focus-colour) !important;
    border-radius: 4px;

}
