}

.domain-tree summary {
    cursor: pointer;
}

.domain-tree summary:focus-visible {
    outline: 2px solid #005fcc;
    outline-offset: 2px;
}



/* Optional extra highlight for text inputs */
textarea {
	resize: none !important;
	min-height: 8em;
}
input:focus-visible,
textarea:focus-visible,
select:focus-visible,
.cf-open-answer__input:focus-visible,
.cf-text-box:focus-visible,
.cf-text-box--number:focus-visible {
	outline: var(--focus-width) solid var(--focus-colour) !important;
}

/* Buttons */
.cf-navigation-next:focus-visible,
.cf-navigation-back:focus-visible,
.SRC_navigation_save:focus-visible {
    text-decoration: underline;
}

/* Links */
