//WG - convert UTC time to local Melbourne call centre time
function UTCToMelbourne(dateValue) {
    if (!dateValue) return '';
    return new Date(dateValue).toLocaleString(
        'en-AU', 
        {
            timeZone: 'Australia/Sydney',
            hour12: false
        }
    );
}

// set skip code to unanswered questions - questions must be non-mandatory
// default skip code set to 1000 - use List_Skip reusable list
// add this function to questions custom validation, or uncomment in global validation
// uncomment hideSkipCode() in 'Look & feel' in JavaScript section
function setSkipCode(code='1000') {
    var q = f(CurrentForm());

    if (q.getType() == "3DGrid") { // multi grid
        var questionIds = Get3DGridQuestionIds(CurrentForm());

        var emptyRows = questionIds.filter(function (item) {
            return !f(item).toBoolean();
        });

        if (
            String(questionIds).split(",")[0].includes(`,${code},`) ||
            String(questionIds).split(",")[0].startsWith(`${code},`) ||
            String(questionIds).split(",")[0].endsWith(`,${code}`)
        ) {
            if (emptyRows.length > 0) {
                var cat = a(CurrentForm()).toString();

                if (
                    cat.includes(`,${code},`) ||
                    cat.startsWith(`${code},`) ||
                    cat.endsWith(`,${code}`)
                ) {
                    skipMessage();

                    emptyRows.forEach(function (item) {
                        if (f(item).item(code).DICHOTOMY) {
                            f(item).item(code).set('1');
                        }
                    });
                }
            }

            questionIds.forEach(function (item) {
                if (f(item).size() > 1) {
                    f(item).item(code).set('0');
                }
            });

        }
    } else if (q.COMPOUND) {
        var rows = q.domainValues();
        var firstRow = CurrentForm() + "_" + rows[0];

        if (f(firstRow).CODED) { // single grid
            var cat = a(firstRow).toString();

            if (
                cat.includes(`,${code},`) ||
                cat.startsWith(`${code},`) ||
                cat.endsWith(`,${code}`)
            ) {
                var emptyRows = rows.filter(function (item) {
                    return !f(CurrentForm() + "_" + item).toBoolean();
                });

                if (emptyRows.length > 0) {
                    skipMessage();

                    emptyRows.forEach(function (item) {
                        f(CurrentForm() + "_" + item).set(code);
                    });
                }
            }

        } else if (!q.toBoolean()) { // standard multi
            var cat = a(CurrentForm()).toString();

            if (
                cat.includes(`,${code},`) ||
                cat.startsWith(`${code},`) ||
                cat.endsWith(`,${code}`)
            ) {
                if (q.item(code).DICHOTOMY) {
                    skipMessage();
                    q.item(code).set('1');
                }
                if (q.size()>1) {
                    q.item(code).set('0');
                }
            }
        }

    } else if (!q.toBoolean()) { // standard single
        var cat = a(CurrentForm()).toString();

        if (
            cat.includes(`,${code},`) ||
            cat.startsWith(`${code},`) ||
            cat.endsWith(`,${code}`)
        ) {
            if (q.CODED) {
                skipMessage();
                q.set(code);
            }
        }
    }

    function skipMessage() {
        RaiseError();
        ClearQuestionErrorMessage();
        ClearErrorMessage();
        SetQuestionErrorMessage(
            LangIDs.en_au,
            "Please provide an answer if you can. If you prefer not to answer this question, click Next to continue."
        );
    }
}

function customErrorMsg_ENG(msg) {

     var lang = CurrentLang();

    RaiseError();
    ClearErrorMessage();
    ClearQuestionErrorMessage();
    SetQuestionErrorMessage(lang, msg);
}

function getProjectSettings(name) {
  const projectSettings = {
    // This might not be the same as the src_job_id. 
    // If you need to dedupe across multiple separate Forsta surveys, you would set them
    // all to have the same value below
    DEDUPE_PROJECT_CODE: "SRC9153",
    // set as a single string, NO spaces
    //e.g. LinA, ORU, Octopus, Pureprofile, Lightspeed, Open (for open link), Client
    PANEL_NAME: " LinA top up",
    // Set the country code for whehre the survey is running. Is used by RD to detect country mismatches and 
    // block respondents for entering the survey
    // NZ for New Zealand etc (Can only set to one single country)
    COUNTRY_CODE: "AU",
    // Controls whether the screen containing Research Defender is automatically submitted
    // once the API queries have completed or the timeout is reached, whichever happens first.
    //
    // Useful when Research Defender is placed on an intermediate screen and respondents
    // should continue automatically without clicking Next.
    AUTO_SUBMIT: false,
  };
  return projectSettings[name];
}

