const MaxEmailTry=9

let emaillocal = f('CONTACTINFONEW_Email_2_other').get()
f('RecruitEmailCollected').set(f('CONTACTINFONEW_Email_2_other').get())

var re1 = /&/;
var simpleEmailRex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (re1.test(emaillocal)) {
        RaiseError();
        ClearQuestionErrorMessage();
        ClearErrorMessage();
        SetQuestionErrorMessage(LangIDs.en_au, "Something went wrong. Please try another email.");
} else if (!simpleEmailRex.test(emaillocal)) {
        //Please provide a valid email address.
        errormessage(3);
} else {
    if(f('CONTACTINFONEW_Email_2_other').toBoolean()) {
        var emailtrycount=Number(f('EmailValidationMaxTry').get()||0)
        emailtrycount = emailtrycount+1
        f('EmailValidationMaxTry').set(emailtrycount)

        if (emailtrycount<MaxEmailTry) {
            //To validate email via Validity API service
            //Request the tempory key
            var APIKey = "redacted"
            var requestString =  "https://api.everest.validity.com/api/2.0/validation/addresses/";        
            requestString = requestString + f('CONTACTINFONEW_Email_2_other').get();
            var response = Http.Get(requestString,"",{"X-API-Key":APIKey});

            if (response == null || response == "" || response == "undefined") {
                //We were unable to validate the email address. Please try again.
                errormessage(18);
            } else {
                var jsonObj = JSON.parse(response);
                var resultReturn = jsonObj["results"];

                if (resultReturn && resultReturn["category"] != null) {
                    var resultCategory = String(resultReturn["category"]).toLowerCase();                
                    f('RecruitEmailCollectedEmailReturnValues_category').set(resultCategory);
                    f('RecruitEmailReturnText').set(JSON.stringify(resultReturn))    

                    var returnvalueCat = f('RecruitEmailCollectedEmailReturnValues_category').get()

                    if (returnvalueCat.includes("email_domain_invalid")) {
                        //Domain for email (AFTER '@') does not exist, please double check it.
                        errormessage(14);
                    } else if (returnvalueCat.includes("email_address_invalid")) {
                        //Email address does not exist, please double check your answer.
                        errormessage(15);
                    } else if (returnvalueCat.includes("email_account_invalid")) {
                        //Email account does not exist, please double check your answer.
                        errormessage(16);
                    } else if (returnvalueCat.includes("accept_all") || returnvalueCat.includes("role_address") || returnvalueCat.includes("disposable")) {
                        //Email address is possibly invalid, please double check your answer.
                        errormessage(17);
                    }
                }
            }
        } else {
            ////Do nothing is maxtry reached
            //     RaiseError();
            //     ClearQuestionErrorMessage();
            //     ClearErrorMessage();
            //     SetQuestionErrorMessage(LangIDs.en_au, "Sorry, we cannot validate the email you entered at the moment. Please call the Social Research Centre on 1800 023 040 or email LifeInAus@srcentre.com.au.");
        }
    }
}

