}

// creating the new recordid
var prefix = 'K' + '3'; // K gets filtered from pipeline and 3 makes this job unique; Updatet each wave
var suffix = CurrentID().toString();
var totalLength = 8;
var new_recordid = prefix + (suffix).padStart(totalLength-1, '0');
f('new_recordid').set(new_recordid);

// creating the panellist
var fieldNames = ["email", "recordid"];
var fieldValues = [f('RecruitEmailCollected_PG').get(), new_recordid];
var result = CreatePanelist(fieldNames, fieldValues);
f('email_existed_in_panel').set(0);

if (result == -1) {
    // error on the survey end, for example not being able to connect to the panel db etc
    RaiseError();
    SetErrorMessage(LangIDs.en,"Unknown error: Couldn't register new panellist. Error code:" + result);
} else if (result == -2) {
    // The unique constraint is violated, i.e. a panelist already exists with the provided values in the unique 
    // fields (email + any user provided unique fields)
    // We will use email_existed_in_panel to conditionally execute to a stop block
     f('email_existed_in_panel').set(1);
} else if (result == -3) {
    // Other database errors when inserting the new panelist.
    RaiseError();
    SetErrorMessage(LangIDs.en,"Unknown error: Couldn't register new panellist. Error code:" + result);
} else if (result == -5) {
    // The password failed on one or more of the password complexity rules, according to the Panel settings for 
    // password complexity.
    RaiseError();
    SetErrorMessage(LangIDs.en,"Password does not comply with password complexity rules. Please choose a different password.");
} else {
    // do nothing
}

if (f('NAMECHK').any('1')) {
 if (GetSurveyChannel()=="Cati")
{
    Redirect(GetCatiRespondentUrl("NAMENEW"));
}
else
{
    Redirect(GetRespondentUrl("NAMENEW"), true);
}

}

if (f('STATECHK').any('1')) {
 if (GetSurveyChannel()=="Cati")
{
    Redirect(GetCatiRespondentUrl("QP_STATE"));
}
else
{
    Redirect(GetRespondentUrl("QP_STATE"), true);
}   
}

