var qid="QPOSTCODE"
var FinalPostcode ="FinalPostcode"
var FinalSuburb ="FinalSuburb"
var FinalState = "FinalState"
var qinput=qid+"_input"

$("#"+FinalPostcode).hide()
$("#" + FinalSuburb).hide()
$("#" + FinalState).hide()

     const sourceData = AustraliaPcode2025 .map(item => ({
        pcode: item[0],   // shown in dropdown
        suburb: item[1] ,
        stateshort:item[2],
        value: item[0] + " "+item[1] +", "+item[2]   // filled into input

    }));
var stateresp = "^f('QP_STATE').valueLabel()^"

const filteredSourceData = sourceData.filter(item =>
  item.stateshort === stateresp
);

$("#"+qinput).autocomplete({
        minLength: 3,
        source: filteredSourceData,
        select: function (event, ui) {

            Confirmit.page.getQuestion(qid).setValue(ui.item.value);
            Confirmit.page.getQuestion(FinalPostcode).setValue(ui.item.pcode);
            Confirmit.page.getQuestion(FinalSuburb).setValue(ui.item.suburb);
            Confirmit.page.getQuestion(FinalState).setValue(ui.item.stateshort);

            return false;
        }
    })
      .on("keydown", function (e) {
    if (e.key === " ") {
      const menu = $(this).autocomplete("widget");
      const active = menu.find(".ui-state-active");

      if (active.length) {
        e.preventDefault(); // stop space being typed
        active.trigger("click"); // select highlighted item
      }
    };})


