   document.querySelector('#^CurrentForm()^_dk_text').innerHTML = "<span style='color: #656565;'>(Don’t know)</span>";
   document.querySelector('#^CurrentForm()^_ref_text').innerHTML = "<span style='color: #656565;'>(Refused)</span>";
}
else {
