$(function () {
  // Month list
  var months = [
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December"
  ];

  // Build an array of objects: { label, value, num }
  // num = "1".."12" (month number as string)
  var monthsData = $.map(months, function (name, index) {
    var monthNum = (index + 1).toString(); // 1-based
    return {
      label: name,     // what autocomplete shows
      value: name,     // what goes into the input
      num: monthNum    // numeric code for Forsta question
    };
  });

  $("#QBIRTHMTHYR_QP_DOB_MTH_input").autocomplete({
    minLength: 1,

    // Custom source: match on text OR number
    source: function (request, response) {
      var term = $.trim(request.term.toLowerCase());

      var results = $.grep(monthsData, function (item) {
        // 1) Match start of month name (e.g. "j", "ja", "jan")
        var byName = item.label.toLowerCase().indexOf(term) === 0;

        // 2) Match numeric prefix: "1" matches 1, 10, 11, 12
        var byNumber = item.num.indexOf(term) === 0;

        return byName || byNumber;
      });

      response(results);
    },

    // When user picks a month, set the coded value in the Forsta question
    select: function (event, ui) {
      // ui.item.num  = "1".."12" (code)
      // ui.item.value = month name
      //Confirmit.page.getQuestion('QBIRTHMTHYR').setValue(ui.item.num, ui.item.value);
      Confirmit.page.getQuestion('QBIRTHMTHYR').setValue('QP_DOB_MTH', ui.item.value)
    }
  });
});

