var yearerror,montherror
if(f('QBIRTHMTHYR').getNoResponseValue()== null)
{
  var monthtxt = f('QBIRTHMTHYR').item('QP_DOB_MTH').toString().trim()
  var year = f('QBIRTHMTHYR').item('QP_DOB_YR').toString().trim()

  var yearRegex = /^\d{4}$/
  if (year!=null||year===""){
   if (!yearRegex.test(year) || (year < 1906 || year > 2026))
    {
      yearerror =true
    }
  }
  month = monthToNumber(monthtxt)

   if (year ==2026 && month>10)
 {

    RaiseError();
    ClearQuestionErrorMessage();
    ClearErrorMessage();
    SetQuestionErrorMessage(LangIDs.en_au, "Please provide a valid date.");
 }

  if (month==null || (month>12 || month<0))
 {

    RaiseError();
    ClearQuestionErrorMessage();
    ClearErrorMessage();
    SetQuestionErrorMessage(LangIDs.en_au, "Please select type in letters and select from the dropdown list.");
 }

   if (yearerror)
 {

    RaiseError();
    ClearQuestionErrorMessage();
    ClearErrorMessage();
    SetQuestionErrorMessage(LangIDs.en_au, "Year must be within 1906 .. 2026");
 }
}

function monthToNumber(month) {
  // normalize to lowercase
  if (!month) {

    return null;
}
  var m = month.toString().toLowerCase()

  if (m === "january") return 1;
  if (m === "february") return 2;
  if (m === "march") return 3;
  if (m === "april") return 4;
  if (m === "may") return 5;
  if (m === "june") return 6;
  if (m === "july") return 7;
  if (m === "august") return 8;
  if (m === "september") return 9;
  if (m === "october") return 10;
  if (m === "november") return 11;
  if (m === "december") return 12;

  return null; // not a valid month
}
