function getFilteredElectorate(QID){
    var electstate_sub = set()

    var allcodes = f(QID).domainValues(); 
    var stateLabel = f('QP_STATE').valueLabel().toUpperCase().trim()
     var code_firstdigit
         if (stateLabel.length==3 || stateLabel.length==2)
    {
        if (stateLabel=='NSW')
        {
                code_firstdigit=1
        }
        else if(stateLabel=='VIC')
        {
            code_firstdigit=2
        }
        else if(stateLabel=='QLD')
        {
            code_firstdigit=3
        }
        else if(stateLabel=='SA')
        {
            code_firstdigit=4
        }
        else if (stateLabel == 'WA') {
            code_firstdigit = 5
        }
        else if(stateLabel=='TAS')
        {
            code_firstdigit=6
        }
        else if(stateLabel=='NT')
        {
            code_firstdigit=7
        }    
        else if (stateLabel == 'ACT') {
                code_firstdigit = 8
            }              

    }

    for (var i = 0; i < allcodes.length; i++) {
        var code = allcodes[i];

        if (code.toString().substring(0, 1) == code_firstdigit) {
            electstate_sub.add(code);
        }


    }

    return electstate_sub
}

