function GetABS_tk(surveyId,respId) {
    //surveyId=p821891461154 (LinA main test job)
    //respid=1
    try {

        var access_token = Authenticate();
        var endpoint = "https://surveys.srcentre.com.au/v1/surveys/" + surveyId + "/respondents/data/" + respId + "?variables=ABS_tk";
        var header = "Authorization: Bearer " + access_token;
        var payload = null;

        var postResult = Http.Get(endpoint, payload, header);
        var resultJson = JSON.parse(postResult);
        var abs_tk = resultJson["ABS_tk"];

        return abs_tk;


    } catch (e) {

        return e;

    }

}


function UpdateABS_tk(surveyId,respId,ABS_tk) {
     try{

        var access_token = Authenticate();
        var endpoint = "https://surveys.srcentre.com.au/v1/surveys/" + surveyId + "/respondents/data";
        var header = "Authorization: Bearer " + access_token;
        var payload = {
    "dataSchema": {
        "keys": ["respid"],
        "variables": ["ABS_tk"]
    },
    "data": [
        {
            "respid": respId,
            "ABS_tk": ABS_tk

        }
    ]
};

        var postResult = Http.PutJson(endpoint, payload, header);


       } catch (e) {

        return e;

    }  

}

function Authenticate() {

    var clientId = "redacted";
    var clientSecret = "redacted";    

    var auendpoint = "https://surveys.srcentre.com.au/identity/connect/token";
    var data = "client_id=" + clientId + "&client_secret="redacted"&grant_type=api-user&scope=pub.surveys";
    var result = Http.Post(auendpoint, data, null);

    var decoded = JSON.parse(result);
    if (!decoded.access_token || decoded.access_token == null || decoded.access_token == undefined) {
        return null;
    }
    return decoded.access_token;

}

