function callABSAPI(endpoint, data, header, codeFieldPrefix) { 

    var response;
    var json;
    var trycount=0;
    try{
     response = Http.PostJson(endpoint, data, header);
    json = JSON.parse(response);  
    f(codeFieldPrefix + '_returned').set(response);

    }  catch (e) {


        trycount=trycount+1;
 } 


 //f('statuscode').set(json.codeStatus)

    if (trycount>0 ||json.codeStatus !="successful") {

       f('ABS_AWS_TOKEN').set(getBearerToken())
        //SetRespondentRecordValues(1, {"ABS_tk": f('ABS_AWS_TOKEN').get()});
        //UpdateABS_tk('p818044815643',1,f('ABS_AWS_TOKEN').get())
         UpdateABS_tk('p818044815643',"1",f('ABS_AWS_TOKEN').get()) 
         try {
         var headerupdated = { 'Authorization':f('ABS_AWS_TOKEN').get(),'User-Agent':'theSocialResearchCentre/forstasurvey'};
        response = Http.PostJson(endpoint, data, headerupdated);
        json = JSON.parse(response);   
        f(codeFieldPrefix + '_returned').set(response);

       } catch (e) {

       } 
    }


    if (json.codeStatus === "successful" && json.result.length > 0) {
        //f(codeFieldPrefix + '_code').set(json.result[0].codeCategory);
        //auto-fill trailing zeros, so it always returns 6 digit code
        var paddedCode = json.result[0].codeCategory.toString().padEnd(6, '0');
        f(codeFieldPrefix + '_code').set(paddedCode);
